{"cards": [{"node_code": "N_52933e03af1585eb", "definition": "研究支撑物流业务运行的基础信息技术，涵盖物流信息系统（如WMS、TMS、OMS）架构、数据库管理、条码/RFID等自动识别技术及物流大数据分析基础。", "boundary": "本节点聚焦于物流领域的“软件与数据”层面，即信息如何被采集、存储、处理和呈现。若侧重硬件设备集成与自动化控制归入智慧物流系统设计；若侧重物理感知层（传感器、网络）归入物流物联网应用。本节点不包含通用计算机理论，仅关注其在物流场景下的应用实现。", "includes": ["物流管理信息系统（WMS/TMS/OMS等）的设计与开发", "物流自动识别技术（条码、RFID、OCR）及数据采集", "物流大数据分析、数据挖掘及可视化技术"], "excludes": ["物流自动化硬件设备与机器人控制（归入智慧物流系统设计）", "物流传感器、通信协议及感知网络（归入物流物联网应用）", "纯计算机算法理论或通用软件工程（归入计算机类）"], "sibling_distinctions": [{"other_code": "N_fcd624be28bb0c84", "rule": "本节点侧重信息处理软件、数据管理及识别技术；兄弟节点侧重将信息技术与物理设备集成的系统架构与自动化控制。"}, {"other_code": "N_3d43341db2c89723", "rule": "本节点侧重数据在系统中的流转、处理与应用；兄弟节点侧重物理世界的感知、标识及数据传输网络。"}], "cross_boundary_rule": "涉及物流信息系统的通用数据库或操作系统技术归入计算机类；涉及物流数据的安全加密归入信息安全类。"}, {"node_code": "N_fcd624be28bb0c84", "definition": "研究智慧物流系统的整体架构、自动化设备集成及智能控制策略，涵盖AGV/AMR调度、智能分拣系统、无人仓/无人车系统设计与物流机器人应用。", "boundary": "本节点聚焦于“软硬结合”的系统工程层面，即如何将信息技术（算法、软件）与物理设备（机器人、传送带、传感器）整合为高效运行的智慧系统。若侧重纯软件算法归入现代物流信息技术；若侧重底层感知硬件归入物流物联网应用。本节点强调系统的整体性、自动化与智能化控制。", "includes": ["物流自动化系统（智能分拣、自动立体库）设计与集成", "移动机器人（AGV/AMR）调度算法与集群控制", "无人仓、无人配送车等智慧物流场景的系统架构"], "excludes": ["纯物流管理软件功能开发（归入现代物流信息技术）", "物流传感器、RFID标签及通信网络底层技术（归入物流物联网应用）", "纯机械结构设计或电气控制理论（归入机械工程或电气类）"], "sibling_distinctions": [{"other_code": "N_52933e03af1585eb", "rule": "本节点侧重物理设备与软件的集成、自动化控制及系统架构；兄弟节点侧重信息处理、数据管理及识别技术本身。"}, {"other_code": "N_3d43341db2c89723", "rule": "本节点侧重利用感知数据进行的系统级决策与控制；兄弟节点侧重感知数据的采集、标识及传输技术。"}], "cross_boundary_rule": "涉及物流机器人的机械结构设计归入机械工程；涉及物流系统的运筹学优化算法归入运筹学或系统工程。"}, {"node_code": "N_3d43341db2c89723", "definition": "研究物联网技术在物流场景中的具体应用，涵盖RFID、GPS/北斗定位、传感器网络、电子标签及物流追踪溯源系统，侧重物理对象的数字化感知与连接。", "boundary": "本节点聚焦于物流领域的“感知与连接”层面，即如何通过物联网技术实现货物、车辆、设施的状态感知、位置追踪及数据互联。若侧重数据在系统中的处理归入现代物流信息技术；若侧重基于感知数据的自动化控制归入智慧物流系统设计。本节点强调物理世界与信息世界的映射。", "includes": ["物流RFID应用、电子标签及自动识别感知", "物流车辆与货物的GPS/北斗定位及轨迹追踪", "物流传感器网络、环境监测及智能仓储感知系统"], "excludes": ["物流信息系统的数据处理与业务逻辑（归入现代物流信息技术）", "基于感知数据的自动化设备控制与调度（归入智慧物流系统设计）", "通用通信协议、5G技术或网络架构（归入通信类）"], "sibling_distinctions": [{"other_code": "N_52933e03af1585eb", "rule": "本节点侧重物理感知、标识及数据传输；兄弟节点侧重数据在业务系统中的存储、处理及应用。"}, {"other_code": "N_fcd624be28bb0c84", "rule": "本节点侧重感知层技术与数据互联；兄弟节点侧重利用感知数据实现的系统级自动化控制与集成。"}], "cross_boundary_rule": "涉及物流物联网的通信协议、5G/6G技术归入通信类；涉及物流传感器的材料或物理原理归入电子或材料类。"}]}
